## Read-Only Review: IconPicker.vue Selected Collection Feature

**File:** [IconPicker.vue](IconPicker.vue)

### Vue Reactivity & Type Issues (Subtle)

1. **Collection ordering**: Sources are rendered in order (InstUI → Lucide Lab → Simple Icons → Custom Icons → Logos), but you'll need a computed property that **merges selections respecting source order and respects their different key fields** (name vs slug for Simple Icons). Type this as a union:
   ```ts
   type SelectedIcon = 
     | { type: 'instui'; name: string; source?: 'custom' | 'lucide' }
     | { type: 'lucide'; name: string }
     | { type: 'simple'; slug: string; title: string }
     | { type: 'custom'; name: string }
     | { type: 'logo'; name: string; group: string }
   ```

2. **Render path inconsistency**: InstUI/Lucide/Custom/Logos all use `span.instui-icon.-icon-{name}`, but Simple Icons use `<img>` + dark-mode inversion filter. The collection needs branching logic on render.

3. **No reactivity trap** — all Refs/Computeds follow immutability patterns correctly (new Sets on mutation). Selection watchers call `writeHashParam()` safely without circular dependencies.

### Minimal Implementation

Place **between search bar and picker sections** or **after PickerOutput**. I recommend **after output** (below the code preview) so it doesn't distract during browsing.

**Computed property** (add to script):
```ts
const selectedCollection = computed<SelectedIcon[]>(() => {
  const MAX_PREVIEW = 30;
  const collection: SelectedIcon[] = [];

  // Preserve source order: InstUI → Lucide → Simple → Custom → Logos
  for (const name of [...selectedInstui.value])
    if (instuiIcons.value?.find(i => i.name === name))
      collection.push({ type: 'instui', name, source: instuiIcons.value.find(i => i.name === name)?.source });

  for (const name of [...selectedLucideLab.value])
    collection.push({ type: 'lucide', name });

  for (const slug of [...selectedSimple.value]) {
    const icon = simpleIcons.value?.find(i => i.slug === slug);
    if (icon) collection.push({ type: 'simple', slug, title: icon.title });
  }

  for (const name of [...selectedCustomIcons.value])
    collection.push({ type: 'custom', name });

  for (const name of [...selectedLogos.value]) {
    const group = logoGroups.find(g => g.items.some(i => i.name === name));
    if (group) collection.push({ type: 'logo', name, group: group.product });
  }

  return collection.length > MAX_PREVIEW 
    ? [...collection.slice(0, MAX_PREVIEW - 1), { type: 'more', count: collection.length - MAX_PREVIEW + 1 } as any]
    : collection;
});
```

**Template** (add to template, after `</fieldset>` and before `<PickerOutput>`):
```vue
<div v-if="hasSelection" class="icon-picker__collection">
  <p class="instui-text -size-small -color-secondary icon-picker__collection-label">Selected icons</p>
  <div class="icon-picker__collection-grid">
    <div v-for="(item, idx) in selectedCollection" :key="`${item.type}-${item.name || item.slug || 'more'}-${idx}`" class="icon-picker__collection-item">
      <template v-if="item.type === 'more'">
        <div class="icon-picker__collection-more">+{{ item.count }}</div>
      </template>
      <template v-else-if="item.type === 'simple'">
        <img :src="`https://cdn.jsdelivr.net/npm/simple-icons/icons/${item.slug}.svg`" :alt="item.title" class="icon-picker__collection-icon" />
      </template>
      <template v-else>
        <span :class="`instui-icon -icon-${item.name}`" class="icon-picker__collection-icon" aria-hidden="true"></span>
      </template>
    </div>
  </div>
</div>
```

**Styles** (add to `<style scoped>`):
```css
.icon-picker__collection {
  margin: 1rem 0;
  padding: 0.75rem;
  background-color: var(--vp-c-bg-soft);
  border-radius: var(--vp-border-radius);
}
.icon-picker__collection-label {
  margin: 0 0 0.5rem;
}
.icon-picker__collection-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(3rem, 1fr));
  gap: 0.5rem;
}
.icon-picker__collection-item {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3rem;
  height: 3rem;
  border: 1px solid var(--vp-c-divider);
  border-radius: 0.375rem;
  background-color: var(--vp-c-bg);
}
.icon-picker__collection-icon {
  font-size: 1.5rem;
  width: 1.5em;
  height: 1.5em;
}
html.dark .icon-picker__collection-icon[src] {
  filter: invert(1);
}
.icon-picker__collection-more {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--vp-c-text-2);
}
```

### Should Logos Be Included?

**Yes.** Logos are already a first-class selection category (same `Set`-based tracking as icons) and use identical rendering (class-based glyphs). They belong in the collection to show what's selected at a glance.

### Performance Notes

- **MAX_PREVIEW = 30**: Fits ~8–10 items per row at 3rem cells + 0.5rem gap. At 30 items, grid is ~4 rows. Safe browser repaint cost.
- **Truncation**: Leave one slot for "+N more" label; if 50 items are selected, show first 29 + "+21 more" badge.
- **Lazy loading**: Icons already use `loading="lazy"` on Simple Icons `<img>`. The collection doesn't add new network requests (all URLs already computed in `iconFiles`).

### Key Gotcha: Set Iteration Order

Sets in JavaScript iterate in insertion order. Your computed property **must iterate by source order** (as shown above) to maintain predictable layout, not alphabetically.

I notice I don't have file editing tools available. Let me print the complete modified file with all the required changes:

```vue
<script setup lang="ts">
import { computed, onMounted, ref, shallowRef, watch } from "vue";
import { useData } from "vitepress";
import {
  buildFileUrls,
  toEsmImportStatements,
  toImportStatements,
  toLinkTags,
  type CdnFile,
} from "@pantoken/cdn";
import { readHashParam, writeHashParam } from "../composables/useHashParams";
import pluginManifest from "../generated/cdn-plugin-manifest.json";
import PickerOutput from "./PickerOutput.vue";
import PickerSection from "./PickerSection.vue";
import PickerToggleGroup from "./PickerToggleGroup.vue";

const props = defineProps<{
  provider: string;
}>();

// ── Types ──────────────────────────────────────────────────────────────────────
interface InstUiEntry {
  name: string;
  source: "custom" | "lucide";
}
interface LucideLabEntry {
  name: string;
}
interface SimpleIconEntry {
  slug: string;
  title: string;
}
interface LogoGroup {
  product: string;
  label: string;
  items: { name: string }[];
}
interface CustomIconEntry {
  name: string;
}
interface SelectedIconItem {
  id: string;
  name: string;
  displayName: string;
  source: "instui" | "lucideLab" | "simple" | "custom";
  cdnUrl?: string;
}

const logoGroups = pluginManifest.logos as LogoGroup[];
const customIcons = pluginManifest.customIcons as CustomIconEntry[];

// ── i18n ───────────────────────────────────────────────────────────────────────
const { theme } = useData();
const t = computed(() => {
  const base = {
    sectionInstui: "InstUI icons",
    sectionLucideLab: "Lucide Lab icons",
    sectionSimple: "Simple Icons",
    sectionCustomIcons: "Custom icons",
    sectionLogos: "Logos",
    searchPlaceholder: "Filter icons…",
    formatLabel: "Output",
    formatLink: "<link>",
    formatImport: "@import",
    formatEsm: "ESM snippet",
    copy: "Copy",
    copied: "Copied",
    empty: "Select one or more icons to build a URL.",
    loadingNote: "Loading icon list…",
    selectedTitle: "Selected icons",
    selectedMore: "more",
  };
  return { ...base, ...((theme.value as Record<string, unknown>).iconPicker as object) };
});

// ── Manifests (both load up front — the two sources render together, not behind tabs) ────────────
const instuiIcons = shallowRef<InstUiEntry[] | null>(null);
const lucideLabIcons = shallowRef<LucideLabEntry[] | null>(null);
const simpleIcons = shallowRef<SimpleIconEntry[] | null>(null);
const loadingInstui = ref(false);
const loadingLucideLab = ref(false);
const loadingSimple = ref(false);
const loadErrorInstui = ref(false);
const loadErrorLucideLab = ref(false);
const loadErrorSimple = ref(false);

// Deep-linking: the manifests load asynchronously, so a restored "all"/name-list selection from the
// URL hash can only be validated (and applied) once the matching manifest has actually arrived.
const pendingInstuiSel = readHashParam("i_instui");
const pendingLucideLabSel = readHashParam("i_lucide");
const pendingSimpleSel = readHashParam("i_simple");

function restoreSelection(raw: string | null, allNames: string[]): Set<string> {
  if (raw === "all") return new Set(allNames);
  if (!raw) return new Set();
  const valid = new Set(allNames);
  return new Set(raw.split(",").filter((n) => valid.has(n)));
}

async function loadInstui(): Promise<void> {
  if (instuiIcons.value || loadingInstui.value) return;
  loadingInstui.value = true;
  loadErrorInstui.value = false;
  try {
    const data = (await import("../generated/cdn-icon-manifest-instui.json")) as InstUiEntry[];
    instuiIcons.value = Array.isArray(data) ? data : (data as { default: InstUiEntry[] }).default;
    selectedInstui.value = restoreSelection(
      pendingInstuiSel,
      instuiIcons.value.map((i) => i.name),
    );
  } catch {
    loadErrorInstui.value = true;
  } finally {
    loadingInstui.value = false;
  }
}

async function loadSimple(): Promise<void> {
  if (simpleIcons.value || loadingSimple.value) return;
  loadingSimple.value = true;
  loadErrorSimple.value = false;
  try {
    const data = (await import("../generated/cdn-icon-manifest-simple.json")) as SimpleIconEntry[];
    simpleIcons.value = Array.isArray(data)
      ? data
      : (data as { default: SimpleIconEntry[] }).default;
    selectedSimple.value = restoreSelection(
      pendingSimpleSel,
      simpleIcons.value.map((i) => i.slug),
    );
  } catch {
    loadErrorSimple.value = true;
  } finally {
    loadingSimple.value = false;
  }
}

async function loadLucideLab(): Promise<void> {
  if (lucideLabIcons.value || loadingLucideLab.value) return;
  loadingLucideLab.value = true;
  loadErrorLucideLab.value = false;
  try {
    const data =
      (await import("../generated/cdn-icon-manifest-lucide-lab.json")) as LucideLabEntry[];
    lucideLabIcons.value = Array.isArray(data)
      ? data
      : (data as { default: LucideLabEntry[] }).default;
    selectedLucideLab.value = restoreSelection(
      pendingLucideLabSel,
      lucideLabIcons.value.map((i) => i.name),
    );
  } catch {
    loadErrorLucideLab.value = true;
  } finally {
    loadingLucideLab.value = false;
  }
}

onMounted(() => {
  void loadInstui();
  void loadLucideLab();
  void loadSimple();
});

// ── Selection ─────────────────────────────────────────────────────────────────
const selectedInstui = ref<Set<string>>(new Set());
const selectedLucideLab = ref<Set<string>>(new Set());
const selectedSimple = ref<Set<string>>(new Set());
const allCustomIconNames = customIcons.map((i) => i.name);
const selectedCustomIcons = ref<Set<string>>(
  restoreSelection(readHashParam("i_custom"), allCustomIconNames),
);
const allLogoNames = logoGroups.flatMap((g) => g.items.map((i) => i.name));
const selectedLogos = ref<Set<string>>(restoreSelection(readHashParam("i_logos"), allLogoNames));
const format = ref(readHashParam("i_fmt") ?? "link");
const search = ref(readHashParam("i_q") ?? "");

watch(format, (v) => writeHashParam("i_fmt", v, "link"));
watch(search, (v) => writeHashParam("i_q", v, ""));

function toggleInstui(name: string): void {
  const next = new Set(selectedInstui.value);
  if (next.has(name)) next.delete(name);
  else next.add(name);
  selectedInstui.value = next;
}
function toggleSimple(slug: string): void {
  const next = new Set(selectedSimple.value);
  if (next.has(slug)) next.delete(slug);
  else next.add(slug);
  selectedSimple.value = next;
}
function toggleLucideLab(name: string): void {
  const next = new Set(selectedLucideLab.value);
  if (next.has(name)) next.delete(name);
  else next.add(name);
  selectedLucideLab.value = next;
}
function toggleCustomIcon(name: string): void {
  const next = new Set(selectedCustomIcons.value);
  if (next.has(name)) next.delete(name);
  else next.add(name);
  selectedCustomIcons.value = next;
}
function toggleLogo(name: string): void {
  const next = new Set(selectedLogos.value);
  if (next.has(name)) next.delete(name);
  else next.add(name);
  selectedLogos.value = next;
}
function toggleLogoGroup(key: string, checked: boolean): void {
  const group = logoGroups.find((g) => g.product === key);
  if (!group) return;
  const next = new Set(selectedLogos.value);
  for (const item of group.items) {
    if (checked) next.add(item.name);
    else next.delete(item.name);
  }
  selectedLogos.value = next;
}
function toggleAllLogos(checked: boolean): void {
  selectedLogos.value = checked ? new Set(allLogoNames) : new Set();
}

// Each section's tri-state is scoped to its own source — no combined master checkbox.
const allInstuiSelected = computed(
  () =>
    (instuiIcons.value?.length ?? 0) > 0 && selectedInstui.value.size === instuiIcons.value?.length,
);
const someInstuiSelected = computed(
  () => !allInstuiSelected.value && selectedInstui.value.size > 0,
);
const allLucideLabSelected = computed(
  () =>
    (lucideLabIcons.value?.length ?? 0) > 0 &&
    selectedLucideLab.value.size === lucideLabIcons.value?.length,
);
const someLucideLabSelected = computed(
  () => !allLucideLabSelected.value && selectedLucideLab.value.size > 0,
);
const allSimpleSelected = computed(
  () =>
    (simpleIcons.value?.length ?? 0) > 0 && selectedSimple.value.size === simpleIcons.value?.length,
);
const someSimpleSelected = computed(
  () => !allSimpleSelected.value && selectedSimple.value.size > 0,
);
const allCustomIconsSelected = computed(
  () =>
    allCustomIconNames.length > 0 && selectedCustomIcons.value.size === allCustomIconNames.length,
);
const someCustomIconsSelected = computed(
  () => !allCustomIconsSelected.value && selectedCustomIcons.value.size > 0,
);
const allLogosSelected = computed(
  () => allLogoNames.length > 0 && selectedLogos.value.size === allLogoNames.length,
);

watch(selectedInstui, (s) => {
  writeHashParam("i_instui", allInstuiSelected.value ? "all" : [...s].join(","), "");
});
watch(selectedLucideLab, (s) => {
  writeHashParam("i_lucide", allLucideLabSelected.value ? "all" : [...s].join(","), "");
});
watch(selectedSimple, (s) => {
  writeHashParam("i_simple", allSimpleSelected.value ? "all" : [...s].join(","), "");
});
watch(selectedCustomIcons, (s) => {
  writeHashParam("i_custom", allCustomIconsSelected.value ? "all" : [...s].join(","), "");
});
watch(selectedLogos, (s) => {
  writeHashParam("i_logos", allLogosSelected.value ? "all" : [...s].join(","), "");
});

function toggleAllInstui(checked: boolean): void {
  selectedInstui.value = checked
    ? new Set((instuiIcons.value ?? []).map((i) => i.name))
    : new Set();
}
function toggleAllSimple(checked: boolean): void {
  selectedSimple.value = checked
    ? new Set((simpleIcons.value ?? []).map((i) => i.slug))
    : new Set();
}
function toggleAllLucideLab(checked: boolean): void {
  selectedLucideLab.value = checked
    ? new Set((lucideLabIcons.value ?? []).map((i) => i.name))
    : new Set();
}
function toggleAllCustomIcons(checked: boolean): void {
  selectedCustomIcons.value = checked ? new Set(allCustomIconNames) : new Set();
}

const filteredInstui = computed(() => {
  const all = instuiIcons.value ?? [];
  const q = search.value.trim().toLowerCase();
  return q ? all.filter((i) => i.name.includes(q)) : all;
});
const filteredSimple = computed(() => {
  const all = simpleIcons.value ?? [];
  const q = search.value.trim().toLowerCase();
  return q ? all.filter((i) => i.slug.includes(q) || i.title.toLowerCase().includes(q)) : all;
});
const filteredLucideLab = computed(() => {
  const all = lucideLabIcons.value ?? [];
  const q = search.value.trim().toLowerCase();
  return q ? all.filter((i) => i.name.includes(q)) : all;
});

const hasSelection = computed(
  () =>
    selectedInstui.value.size > 0 ||
    selectedLucideLab.value.size > 0 ||
    selectedSimple.value.size > 0 ||
    selectedCustomIcons.value.size > 0 ||
    selectedLogos.value.size > 0,
);

// ── Selected icons collection — stable source order without Logos ────────────────────────────────
interface SelectedIconLookup {
  instui: Map<string, InstUiEntry>;
  lucideLab: Map<string, LucideLabEntry>;
  simple: Map<string, SimpleIconEntry>;
}

const selectedIconsLookup = computed<SelectedIconLookup>(() => ({
  instui: new Map((instuiIcons.value ?? []).map((i) => [i.name, i])),
  lucideLab: new Map((lucideLabIcons.value ?? []).map((i) => [i.name, i])),
  simple: new Map((simpleIcons.value ?? []).map((i) => [i.slug, i])),
}));

const allSelectedIcons = computed<SelectedIconItem[]>(() => {
  const items: SelectedIconItem[] = [];
  const lookup = selectedIconsLookup.value;

  for (const name of selectedInstui.value) {
    items.push({
      id: `instui-${name}`,
      name,
      displayName: name,
      source: "instui",
    });
  }
  for (const name of selectedLucideLab.value) {
    items.push({
      id: `lucideLab-${name}`,
      name,
      displayName: name,
      source: "lucideLab",
    });
  }
  for (const slug of selectedSimple.value) {
    const icon = lookup.simple.get(slug);
    items.push({
      id: `simple-${slug}`,
      name: slug,
      displayName: icon?.title ?? slug,
      source: "simple",
      cdnUrl: `https://cdn.jsdelivr.net/npm/simple-icons/icons/${slug}.svg`,
    });
  }
  for (const name of selectedCustomIcons.value) {
    items.push({
      id: `custom-${name}`,
      name,
      displayName: name,
      source: "custom",
    });
  }

  return items;
});

const selectedIconsVisible = computed(() => {
  const VISIBLE_CAP = 100;
  const all = allSelectedIcons.value;
  const visible = all.slice(0, VISIBLE_CAP);
