const SIMPLE_ICONS_PKG = "@pantoken/plugin-simple-icons";
const LUCIDE_LAB_PKG = "@pantoken/plugin-lucide-lab";
const CUSTOM_ICONS_PKG = "@pantoken/plugin-custom-icons";
